#!/bin/bash
# Fetch external artifacts for this environment.
#
# This benchmark uses no external datasets or pretrained weights: its scene
# inputs (data/scenes/*.npz) and evaluator answers are deterministic files
# generated by this repository's scene builder and tracked in git, and all
# Python packages are installed by environment/setup.sh. There is therefore
# nothing to download; the script only checks that the tracked scene files are
# intact so a broken checkout fails early.
#
# Estimated total download size: 0 GB

set -e

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "$ROOT_DIR"

mkdir -p data/downloads
python3 - <<'PY'
import json
from pathlib import Path

manifest = json.loads(Path("data/scenes/manifest.json").read_text())
missing = [s["file"] for s in manifest["scenes"] if not (Path("data/scenes") / s["file"]).is_file()]
if missing:
    raise SystemExit(f"missing tracked scene files: {missing} (re-checkout data/scenes from git)")
print(f"{len(manifest['scenes'])} scene files present in data/scenes")
PY
